// oxlint-disable-next-line import/no-unassigned-import -- server-only is a side-effect-only guard that fails client bundles
import "server-only"
// oxlint-disable-next-line import/no-nodejs-modules -- local development reads the git-ignored json generated by @ts-items/feature-flags
import { readFile } from "node:fs/promises"
// oxlint-disable-next-line import/no-nodejs-modules -- resolves the path relative to the working directory of next
import path from "node:path"

/**
 * @description
 * 実行時のカレントディレクトリからのパス(絶対パスも可)にある json ファイルを読み込み、パース前の値を返す。
 * ファイルが無いときや json として不正なときは reject する
 */
export const readJson = async (filePath: string): Promise<unknown> => {
  const text = await readFile(path.resolve(process.cwd(), filePath), "utf8")

  return JSON.parse(text)
}
